import React, { useState, useRef, useEffect } from 'react';
import { 
  Upload, 
  Image as ImageIcon, 
  Loader2, 
  ArrowRight, 
  Box, 
  Circle, 
  Image as LucideImage, 
  Pencil, 
  Rocket 
} from 'lucide-react';
import { Flow } from 'flow-sdk';
import { ThreeViewport, ViewportHandle } from './components/ThreeViewport';
import { Sidebar } from './components/Sidebar';
import { GenHistoryItem, SceneObject, SceneObjectType } from './types';
import { spaceshipModelUrl } from './spaceshipModel';

// Pre-calculate stable Blob URL for embedded model
const getStableModelUrl = (dataUrl: string) => {
  if (!dataUrl.startsWith('data:')) return dataUrl;
  const [header, base64] = dataUrl.split(',');
  const mime = header.split(':')[1].split(';')[0];
  const byteString = atob(base64);
  const ab = new ArrayBuffer(byteString.length);
  const ia = new Uint8Array(ab);
  for (let i = 0; i < byteString.length; i++) ia[i] = byteString.charCodeAt(i);
  const blob = new Blob([ab], { type: mime });
  return URL.createObjectURL(blob);
};

const STABLE_SPACESHIP_URL = getStableModelUrl(spaceshipModelUrl);

type ViewMode = '3D' | 'Image';

export default function App() {
  const [modelUrl, setModelUrl] = useState<string | null>(STABLE_SPACESHIP_URL);
  const [backgroundUrl, setBackgroundUrl] = useState<string | null>(null);
  const [sceneObjects, setSceneObjects] = useState<SceneObject[]>([]);

  const [appliedFocalLength, setAppliedFocalLength] = useState<number | string>(50);
  const [focalLengthInput, setFocalLengthInput] = useState<string>('50');
  const [framePrompt, setFramePrompt] = useState('');
  const [isDrawingMode, setIsDrawingMode] = useState(false);
  const [drawColor, setDrawColor] = useState('#ef4444');

  const [viewMode, setViewMode] = useState<ViewMode>('3D');
  const [isGenerating, setIsGenerating] = useState(false);
  const [history, setHistory] = useState<GenHistoryItem[]>([]);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const viewportRef = useRef<ViewportHandle>(null);
  const modelInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const addObject = (type: SceneObjectType) => {
    if (type === 'Image') {
      imageInputRef.current?.click();
      return;
    }
    setModelUrl(null);
    const newObj: SceneObject = {
      id: Math.random().toString(36).substr(2, 9),
      type,
      position: [0, 0, 0]
    };
    setSceneObjects([newObj]);
    setViewMode('3D');
    viewportRef.current?.resetCamera();
  };

  const handleModelUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setSceneObjects([]);
      setModelUrl(url);
      setViewMode('3D');
      viewportRef.current?.resetCamera();
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const url = URL.createObjectURL(file);
      setBackgroundUrl(url);
      setViewMode('3D');
    }
  };

  const handleApplyFocalLength = () => {
    setAppliedFocalLength(focalLengthInput);
  };

  const handleGenerateImage = async () => {
    if (!framePrompt) return;
    setError(null);
    setIsGenerating(true);

    try {
      const cap = await viewportRef.current?.capture();
      if (!cap) throw new Error("Failed to capture viewport");

      const mimeType = 'image/jpeg';
      const rawBase64 = cap.split(',')[1];

      const savedMedia = await Flow.save({
        base64: rawBase64,
        mimeType,
        name: 'Viewport Screenshot'
      });

      if (!savedMedia?.mediaId) throw new Error("Failed to persist reference image");

      const structuredPrompt = `You are a versatile and highly skilled 3D conceptual artist. 

YOUR ABSOLUTE PRIORITY: You must use the provided image as a STRICT structural and compositional guide. The final output must perfectly match the perspective, scale, and positioning of all elements (3D gray geometry, background image, and hand-drawn annotations) seen in the viewport screenshot.

STYLE GUIDANCE:
- The artistic style of the final output is DETERMINED ENTIRELY by the User Request. 
- If the user asks for "photorealistic," "cartoon," "claymation," "oil painting," "blueprint," or any other specific aesthetic, you must execute that style flawlessly.
- If no specific style is provided, default to high-fidelity photorealistic rendering.

YOUR TASK:
1. Interpret the simple 3D "clay" shapes as the primary volumes and subjects of the scene.
2. Interpret all hand-drawn colored annotations/sketches as CONCEPTUAL GUIDES for new details, modifications, or specific artistic intent.
3. Integrate these elements into a cohesive, finished artwork while maintaining the exact spatial composition of the viewport.
4. CRITICAL: Do not render raw hand-drawn lines or the gray background in the final output. Transform them into the requested style seamlessly.

User Request: ${framePrompt}`;

      const res = await Flow.generate.image({ 
        prompt: structuredPrompt, 
        referenceImageMediaIds: [savedMedia.mediaId],
        modelDisplayName: 'Nano Banana Pro',
        aspectRatio: '16:9'
      });

      const newImage = `data:${res.mimeType};base64,${res.base64}`;
      setGeneratedImage(newImage);
      setViewMode('Image');

      const cameraState = viewportRef.current?.getCameraState() || { focalLength: Number(appliedFocalLength) || 50, position: [0,0,5], rotation: [0,0,0] };

      const newItem: GenHistoryItem = {
        id: Math.random().toString(36).substr(2, 9),
        prompt: framePrompt,
        camera: cameraState,
        generatedImage: newImage,
        isPending: false
      };

      setHistory(prev => [newItem, ...prev]);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Generation failed");
    } finally {
      setIsGenerating(false);
    }
  };

  const restoreFromHistory = (item: GenHistoryItem) => {
    if (item.isPending) return;
    setFramePrompt(item.prompt);
    setAppliedFocalLength(item.camera.focalLength);
    setFocalLengthInput(String(item.camera.focalLength));
    if (item.generatedImage) {
      setGeneratedImage(item.generatedImage);
      setViewMode('Image');
    }
  };

  return (
    <div className="h-screen w-screen bg-zinc-950 text-zinc-100 flex overflow-hidden font-sans p-4 gap-4">

      <div className="flex-1 flex flex-col gap-4 min-w-0">

        {/* Physical Viewport Container */}
        <div className="flex-1 flex items-center justify-center bg-black rounded-[32px] border border-[#27272a] shadow-2xl overflow-hidden relative group">

          {/* 
            The "Stage" - A 16:9 box that physically "covers" the parent frame.
            It is centered and scaled to fill both height and width, ensuring
            no black bars while maintaining a perfect 16:9 for alignment.
          */}
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full aspect-video shadow-2xl">

            {/* Viewports - Absolute filling of the 16:9 Stage */}
            <div className={`absolute inset-0 z-10 transition-opacity duration-500 ${viewMode === '3D' ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
              <ThreeViewport 
                ref={viewportRef} 
                modelUrl={modelUrl} 
                backgroundUrl={backgroundUrl} 
                focalLength={appliedFocalLength} 
                objects={sceneObjects} 
                isDrawingMode={isDrawingMode}
                drawColor={drawColor}
                isGenerating={isGenerating}
                viewMode={viewMode}
              />
            </div>

            <div className={`absolute inset-0 z-20 transition-opacity duration-500 ${viewMode === 'Image' ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
              {generatedImage ? (
                <img src={generatedImage} className="w-full h-full object-cover" alt="AI Generated" />
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-500 bg-zinc-900/20">
                  <ImageIcon size={48} strokeWidth={1} className="opacity-20 mb-4" />
                  <p className="text-[10px] uppercase tracking-widest font-bold opacity-30">No image generated yet</p>
                </div>
              )}
            </div>

            {isGenerating && (
              <div className="absolute inset-0 z-40 flex flex-col items-center justify-center bg-black/60 backdrop-blur-md animate-in fade-in duration-300">
                <Loader2 className="animate-spin text-white mb-4" size={32} />
                <p className="text-[10px] uppercase tracking-[0.2em] font-black animate-pulse">Generating...</p>
              </div>
            )}
          </div>

          {/* 
            Controls - Pinned to the visible parent container edges, 
            so they are NEVER cropped out when the 16:9 Stage overflows.
          */}
          <div className="absolute top-6 right-6 z-50 flex gap-2 items-center">
            <div className={`flex items-center bg-zinc-900/80 backdrop-blur-xl p-1 px-4 rounded-full border border-white/10 h-[34px] transition-opacity duration-300 ${viewMode === '3D' ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}>
              <input 
                type="text"
                value={focalLengthInput}
                onChange={(e) => {
                  const val = e.target.value;
                  if (val === '' || /^\d*\.?\d*$/.test(val)) setFocalLengthInput(val);
                }}
                onKeyDown={(e) => e.key === 'Enter' && handleApplyFocalLength()}
                onBlur={handleApplyFocalLength}
                className="w-6 bg-transparent text-[10px] font-bold text-white outline-none text-right selection:bg-white/20"
              />
              <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-wider ml-1">mm</span>
            </div>

            <div className="flex bg-zinc-900/80 backdrop-blur-xl rounded-full border border-white/10 h-[34px] overflow-hidden">
              {(['3D', 'Image'] as ViewMode[]).map((mode) => (
                <button
                  key={mode}
                  onClick={() => setViewMode(mode)}
                  className={`px-6 h-full rounded-full text-[10px] font-bold uppercase tracking-wider transition-all duration-300 ${
                    viewMode === mode 
                      ? 'bg-white text-black shadow-[0_0_20px_rgba(255,255,255,0.2)]' 
                      : 'text-zinc-500 hover:text-white'
                  }`}
                >
                  {mode}
                </button>
              ))}
            </div>
          </div>

          <div className="absolute bottom-6 right-6 z-50 flex flex-col items-end gap-2">
            {isDrawingMode && (
              <div className="flex flex-col gap-2 p-2 bg-zinc-900/80 backdrop-blur-xl rounded-full border border-white/10 animate-in fade-in slide-in-from-bottom-2 duration-300 mb-1">
                {['#ef4444', '#22c55e', '#3b82f6', '#eab308', '#ffffff', '#000000'].map((color) => (
                  <button
                    key={color}
                    onClick={() => setDrawColor(color)}
                    className={`w-6 h-6 rounded-full border-2 transition-transform hover:scale-110 active:scale-90 ${drawColor === color ? 'border-white scale-110 shadow-lg' : 'border-transparent'}`}
                    style={{ backgroundColor: color }}
                  />
                ))}
              </div>
            )}
            <button 
              onClick={() => setIsDrawingMode(!isDrawingMode)}
              className={`w-10 h-10 flex items-center justify-center backdrop-blur-xl rounded-full border border-white/10 transition-all duration-300 ${viewMode === '3D' ? 'opacity-100' : 'opacity-0 pointer-events-none'} ${isDrawingMode ? 'bg-white text-black shadow-[0_0_20px_rgba(255,255,255,0.2)]' : 'bg-zinc-900/80 text-zinc-500 hover:text-white hover:bg-zinc-800'} shadow-xl`}
            >
              <Pencil size={18} />
            </button>
          </div>

          {error && (
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-50 px-6 py-3 bg-red-500/20 backdrop-blur-xl border border-red-500/50 rounded-full text-red-500 text-[10px] font-bold uppercase tracking-wider shadow-2xl animate-in slide-in-from-bottom-4 duration-500">
              {error}
            </div>
          )}
        </div>

        {/* Bottom Controls Area */}
        <div className="flex gap-4 h-[120px] flex-shrink-0">
          <div className="flex-1 flex bg-zinc-900/30 rounded-[32px] border border-[#27272a] p-3 gap-2 overflow-x-auto [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">
            <button 
              onClick={() => {
                setSceneObjects([]);
                setModelUrl(STABLE_SPACESHIP_URL);
                setViewMode('3D');
                viewportRef.current?.resetCamera();
              }}
              className="flex-shrink-0 flex-1 h-full flex flex-col items-center justify-center gap-2 rounded-2xl bg-zinc-900/50 border border-white/5 hover:bg-zinc-800 transition-all group"
            >
              <Rocket size={18} className="text-zinc-500 group-hover:text-white transition-colors" />
              <span className="text-[9px] font-bold uppercase tracking-wider text-zinc-600 group-hover:text-zinc-300">Spaceship</span>
            </button>

            {[
              { label: 'Sphere', icon: Circle, type: 'Sphere' },
              { label: 'Cube', icon: Box, type: 'Cube' },
            ].map((item) => (
              <button 
                key={item.label}
                onClick={() => addObject(item.type as SceneObjectType)}
                className="flex-shrink-0 flex-1 h-full flex flex-col items-center justify-center gap-2 rounded-2xl bg-zinc-900/50 border border-white/5 hover:bg-zinc-800 transition-all group relative"
              >
                <item.icon size={18} className="text-zinc-500 group-hover:text-white transition-colors" />
                <span className="text-[9px] font-bold uppercase tracking-wider text-zinc-600 group-hover:text-zinc-300">{item.label}</span>
              </button>
            ))}

            <button 
              onClick={() => {
                if (backgroundUrl) {
                  setBackgroundUrl(null);
                  setViewMode('3D');
                } else {
                  imageInputRef.current?.click();
                }
              }}
              className="flex-shrink-0 flex-1 h-full flex flex-col items-center justify-center gap-2 rounded-2xl bg-zinc-900/50 border border-white/5 hover:bg-zinc-800 transition-all group relative"
            >
              <LucideImage size={18} className="text-zinc-500 group-hover:text-white transition-colors" />
              <span className="text-[9px] font-bold uppercase tracking-wider text-zinc-600 group-hover:text-zinc-300">
                {backgroundUrl ? 'Clear BG' : 'Backdrop'}
              </span>
              <input type="file" ref={imageInputRef} onChange={handleImageUpload} className="hidden" accept=".png,.jpg,.jpeg,.webp" />
            </button>

            <button 
              onClick={() => modelInputRef.current?.click()}
              className="flex-shrink-0 flex-1 h-full flex flex-col items-center justify-center gap-2 rounded-2xl bg-zinc-900/50 border border-white/5 hover:bg-zinc-800 transition-all group text-zinc-500 hover:text-white"
            >
              <Upload size={18} />
              <span className="text-[9px] font-bold uppercase tracking-wider text-zinc-600 group-hover:text-zinc-300">3D Model</span>
              <input type="file" ref={modelInputRef} onChange={handleModelUpload} className="hidden" accept=".gltf,.glb,.obj" />
            </button>
          </div>

          <div className="flex-1 bg-zinc-900/30 rounded-[32px] border border-[#27272a] relative group transition-all focus-within:border-zinc-700 h-full overflow-hidden">
            <textarea 
              value={framePrompt}
              onChange={(e) => setFramePrompt(e.target.value)}
              placeholder="Describe your 3D composition..."
              className="w-full h-full bg-transparent text-white text-[14px] leading-relaxed resize-none outline-none placeholder:text-zinc-700 font-medium p-6 pr-16 [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden"
            />

            <div className="absolute bottom-6 right-6 z-10">
              <button 
                onClick={handleGenerateImage}
                disabled={isGenerating || !framePrompt}
                className="h-10 w-10 flex items-center justify-center bg-zinc-500/80 text-black rounded-full hover:bg-zinc-400 active:scale-95 transition-all disabled:opacity-30 disabled:scale-100 flex-shrink-0 shadow-xl"
              >
                <ArrowRight size={18} />
              </button>
            </div>
          </div>
        </div>
      </div>

      <Sidebar 
        history={history} 
        onRestore={restoreFromHistory} 
      />
    </div>
  );
}

import React from 'react';
import { Image as ImageIcon } from 'lucide-react';
import { GenHistoryItem } from '../types';

interface Props {
  history: GenHistoryItem[];
  onRestore: (item: GenHistoryItem) => void;
}

export const Sidebar: React.FC<Props> = ({ history, onRestore }) => {
  return (
    <div className="w-96 border border-[#27272a] bg-zinc-900/30 rounded-[32px] flex flex-col h-full overflow-hidden shadow-2xl">
      <div className="flex-1 overflow-y-auto p-4 space-y-3 [scrollbar-width:none] [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden">

        {history.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-zinc-700 gap-2">
            <ImageIcon size={32} strokeWidth={1.5} />
            <p className="text-[10px] font-bold uppercase tracking-widest">Empty History</p>
          </div>
        ) : (
          history.map((item) => (
            <div
              key={item.id}
              onClick={() => onRestore(item)}
              className="group bg-zinc-900 border border-[#27272a] rounded-3xl overflow-hidden shadow-lg transition-all duration-300 cursor-pointer hover:border-zinc-500"
            >
              <div className="relative aspect-video bg-zinc-900 overflow-hidden">
                {item.isPending ? (
                  <div className="w-full h-full relative overflow-hidden bg-zinc-900">
                    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/5 to-transparent -translate-x-full animate-shimmer" />
                  </div>
                ) : item.generatedImage ? (
                  <img src={item.generatedImage} className="w-full h-full object-cover" alt="Generated" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center bg-zinc-900 text-zinc-500 opacity-60">
                    <ImageIcon size={24} strokeWidth={1} />
                  </div>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

import React, { useRef, useImperativeHandle, forwardRef, useMemo, memo, useEffect } from 'react';
import { OrbitControls, PerspectiveCamera, useGLTF } from '@react-three/drei';
import { useFrame, Canvas } from '@react-three/fiber';
import * as THREE from 'three';
import { SceneObject, CameraState } from '../types';

// Use an allowed CDN for the Draco decoder to avoid CSP issues that cause "Failed to fetch" errors.
const DRACO_DECODER_JSDELIVR = 'https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/libs/draco/';

interface Props {
  modelUrl: string | null;
  backgroundUrl: string | null;
  focalLength: number | string;
  objects: SceneObject[];
  isDrawingMode: boolean;
  drawColor: string;
  isGenerating?: boolean;
  viewMode?: string;
}

export interface ViewportHandle {
  capture: () => Promise<string>;
  getCameraState: () => CameraState;
  resetCamera: () => void;
}

const CameraLight = () => {
  const lightRef = useRef<THREE.DirectionalLight>(null);

  useFrame((state) => {
    if (lightRef.current) {
      lightRef.current.position.copy(state.camera.position);
      lightRef.current.quaternion.copy(state.camera.quaternion);
    }
  });

  return <directionalLight ref={lightRef} intensity={2.5} />;
};

const Model = ({ url }: { url: string }) => {
  const { scene } = useGLTF(url, DRACO_DECODER_JSDELIVR);

  const clonedScene = useMemo(() => {
    const clone = scene.clone();
    clone.scale.set(1, 1, 1);
    clone.position.set(0, 0, 0);

    clone.traverse((node) => {
      if ((node as THREE.Mesh).isMesh) {
        const mesh = node as THREE.Mesh;
        mesh.material = new THREE.MeshStandardMaterial({
          color: '#888888',
          roughness: 0.6,
          metalness: 0.0,
        });
      }
    });
    return clone;
  }, [scene]);

  return <primitive object={clonedScene} />;
};

const PrimitiveObject = ({ type, position }: SceneObject) => {
  return (
    <mesh position={position}>
      {type === 'Cube' && <boxGeometry args={[2, 2, 2]} />}
      {type === 'Sphere' && <sphereGeometry args={[1, 32, 32]} />}
      {type === 'Image' && <planeGeometry args={[2, 2]} />}

      <meshStandardMaterial 
        color="#888888" 
        roughness={0.6} 
        metalness={0.0}
      />
    </mesh>
  );
};

const Scene = ({ modelUrl, objects, onCameraMove, isDrawingMode, isGenerating, viewMode, controlsRef }: { modelUrl: string | null; objects: SceneObject[]; onCameraMove: () => void; isDrawingMode: boolean; isGenerating: boolean; viewMode: string; controlsRef: any }) => {
  return (
    <>
      <CameraLight />
      <ambientLight intensity={0.4} />
      <directionalLight position={[10, 20, 10]} intensity={1.0} />
      <directionalLight position={[-10, 5, -5]} intensity={0.5} />

      {modelUrl && <Model url={modelUrl} />}
      {objects.map((obj) => (
        <PrimitiveObject key={obj.id} {...obj} />
      ))}
      {!modelUrl && objects.length === 0 && (
        <mesh position={[0, 0, 0]}>
          <boxGeometry args={[2, 2, 2]} />
          <meshStandardMaterial color="#888888" roughness={0.6} metalness={0.0} />
        </mesh>
      )}
      <OrbitControls 
        ref={controlsRef} 
        makeDefault 
        enableDamping={false} 
        onChange={onCameraMove} 
        enabled={!isDrawingMode && !isGenerating && viewMode === '3D'} 
      />
    </>
  );
};

export const ThreeViewport = memo(forwardRef<ViewportHandle, Props>(({ modelUrl, backgroundUrl, focalLength, objects, isDrawingMode, drawColor, isGenerating = false, viewMode = '3D' }, ref) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const drawingCanvasRef = useRef<HTMLCanvasElement>(null);
  const cameraRef = useRef<THREE.PerspectiveCamera>(null);
  const controlsRef = useRef<any>(null);

  const isDrawing = useRef(false);
  const lastPos = useRef({ x: 0, y: 0 });

  const safeFov = useMemo(() => {
    const mm = typeof focalLength === 'string' ? parseFloat(focalLength) : focalLength;
    if (isNaN(mm) || mm <= 0) return 39.6;
    const fovDegrees = 2 * Math.atan(12 / mm) * (180 / Math.PI);
    return Math.max(0.1, Math.min(170, fovDegrees));
  }, [focalLength]);

  useEffect(() => {
    const resizeCanvas = () => {
      if (containerRef.current && drawingCanvasRef.current) {
        const { clientWidth, clientHeight } = containerRef.current;
        drawingCanvasRef.current.width = clientWidth;
        drawingCanvasRef.current.height = clientHeight;
      }
    };
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    return () => window.removeEventListener('resize', resizeCanvas);
  }, []);

  const startDrawing = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawingMode || isGenerating || viewMode !== '3D') return;
    isDrawing.current = true;
    const rect = drawingCanvasRef.current?.getBoundingClientRect();
    if (rect) {
      lastPos.current = { x: e.clientX - rect.left, y: e.clientY - rect.top };
    }
  };

  const draw = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!isDrawing.current || !drawingCanvasRef.current || !isDrawingMode) return;
    const ctx = drawingCanvasRef.current.getContext('2d');
    if (!ctx) return;

    const rect = drawingCanvasRef.current.getBoundingClientRect();
    const currentPos = { x: e.clientX - rect.left, y: e.clientY - rect.top };

    ctx.beginPath();
    ctx.moveTo(lastPos.current.x, lastPos.current.y);
    ctx.lineTo(currentPos.x, currentPos.y);
    ctx.strokeStyle = drawColor;
    ctx.lineWidth = 4;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.stroke();

    lastPos.current = currentPos;
  };

  const stopDrawing = () => {
    isDrawing.current = false;
  };

  const clearDrawing = () => {
    const cvs = drawingCanvasRef.current;
    if (cvs) {
      const ctx = cvs.getContext('2d');
      if (ctx) {
        ctx.clearRect(0, 0, cvs.width, cvs.height);
        ctx.beginPath();
      }
    }
  };

  useImperativeHandle(ref, () => ({
    capture: async () => {
      const glCanvas = canvasRef.current;
      const drawCanvas = drawingCanvasRef.current;
      if (!glCanvas) return '';

      const rect = glCanvas.getBoundingClientRect();

      // ENSURE 1K+ RESOLUTION: Calculate a target resolution of 1280px on the long side.
      // This ensures the AI receives enough structural detail regardless of your browser's viewport size.
      const targetLongSide = 1280;
      const currentLongSide = Math.max(rect.width, rect.height);
      const scaleFactor = Math.max(1, targetLongSide / currentLongSide);

      const tempCanvas = document.createElement('canvas');
      tempCanvas.width = rect.width * scaleFactor;
      tempCanvas.height = rect.height * scaleFactor;

      const ctx = tempCanvas.getContext('2d');
      if (!ctx) return glCanvas.toDataURL('image/jpeg', 0.9);

      try {
        if (backgroundUrl) {
          const img = new Image();
          img.src = backgroundUrl;
          await new Promise((resolve, reject) => {
            img.onload = resolve;
            img.onerror = reject;
          });

          const imgRatio = img.width / img.height;
          const canvasRatio = tempCanvas.width / tempCanvas.height;
          let drawWidth = tempCanvas.width;
          let drawHeight = tempCanvas.height;
          let offsetX = 0;
          let offsetY = 0;

          if (canvasRatio > imgRatio) {
            drawHeight = tempCanvas.width / imgRatio;
            offsetY = (tempCanvas.height - drawHeight) / 2;
          } else {
            drawWidth = tempCanvas.height * imgRatio;
            offsetX = (tempCanvas.width - drawWidth) / 2;
          }
          ctx.drawImage(img, offsetX, offsetY, drawWidth, drawHeight);
        } else {
            ctx.fillStyle = '#353535';
            ctx.fillRect(0, 0, tempCanvas.width, tempCanvas.height);
        }

        // Draw layers scaled to the high-resolution buffer
        ctx.drawImage(glCanvas, 0, 0, tempCanvas.width, tempCanvas.height);

        if (drawCanvas) {
          ctx.drawImage(drawCanvas, 0, 0, tempCanvas.width, tempCanvas.height);
        }

        // Return high-quality JPEG (0.92) to minimize artifacts for the AI model
        return tempCanvas.toDataURL('image/jpeg', 0.92);
      } catch (err) {
        console.error("Failed to composite high-res capture", err);
        return glCanvas.toDataURL('image/jpeg', 0.9);
      }
    },
    getCameraState: () => {
      if (!cameraRef.current) return { position: [12, 12, 12], rotation: [0, 0, 0], focalLength: 50 };
      const p = cameraRef.current.position;
      const r = cameraRef.current.rotation;
      const mm = typeof focalLength === 'string' ? parseFloat(focalLength) : focalLength;
      return {
        position: [p.x, p.y, p.z],
        rotation: [r.x, r.y, r.z],
        focalLength: isNaN(mm) ? 50 : mm
      };
    },
    resetCamera: () => {
      if (cameraRef.current) {
        cameraRef.current.position.set(12, 12, 12);
        cameraRef.current.updateProjectionMatrix();
      }
      if (controlsRef.current) {
        controlsRef.current.target.set(0, 0, 0);
        controlsRef.current.update();
      }
    }
  }));

  return (
    <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-[#353535]">
      {backgroundUrl && (
        <div 
          className="absolute inset-0 z-0 bg-center bg-cover transition-opacity duration-700" 
          style={{ backgroundImage: `url(${backgroundUrl})` }}
        />
      )}

      <div className="absolute inset-0 z-10">
        <Canvas
          ref={canvasRef}
          gl={{ preserveDrawingBuffer: true, antialias: true, alpha: true }}
        >
          <PerspectiveCamera 
            makeDefault 
            ref={cameraRef} 
            position={[12, 12, 12]} 
            fov={safeFov} 
          />
          {!backgroundUrl && <color attach="background" args={['#353535']} />}

          <React.Suspense fallback={null}>
            <Scene 
              modelUrl={modelUrl} 
              objects={objects} 
              onCameraMove={clearDrawing} 
              isDrawingMode={isDrawingMode} 
              isGenerating={isGenerating} 
              viewMode={viewMode} 
              controlsRef={controlsRef} 
            />
          </React.Suspense>
        </Canvas>
      </div>

      <canvas
        ref={drawingCanvasRef}
        onPointerDown={startDrawing}
        onPointerMove={draw}
        onPointerUp={stopDrawing}
        onPointerOut={stopDrawing}
        className={`absolute inset-0 z-20 touch-none ${isDrawingMode && !isGenerating && viewMode === '3D' ? 'pointer-events-auto cursor-crosshair' : 'pointer-events-none'}`}
      />
    </div>
  );
}));

@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  color-scheme: dark;
}

body {
  margin: 0;
  background-color: #09090b;
}

@keyframes shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

.animate-shimmer {
  animation: shimmer 1.5s infinite;
}

export interface CameraState {
  position: [number, number, number];
  rotation: [number, number, number];
  focalLength: number;
}

export type SceneObjectType = 'Sphere' | 'Cube' | 'Image';

export interface SceneObject {
  id: string;
  type: SceneObjectType;
  position: [number, number, number];
}

export interface GenHistoryItem {
  id: string;
  prompt: string;
  camera: CameraState;
  generatedImage?: string | null;
  isPending?: boolean;
}
